package io.knowledgebrain.gateway;
import java.net.http.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class RecordConceptRoutesTest {
 GatewayTransport transport;GatewayController proxy;String root="/api/spaces/01a10000-0000-7000-8000-000000000000/decisions";
 @BeforeEach @SuppressWarnings("unchecked") void init()throws Exception{transport=mock(GatewayTransport.class);proxy=new GatewayController(transport,new SimpleMeterRegistry(),"https://localhost:8443");HttpResponse<byte[]> response=mock(HttpResponse.class);when(response.statusCode()).thenReturn(200);when(response.body()).thenReturn("{}".getBytes());when(response.headers()).thenReturn(HttpHeaders.of(Map.of("Content-Type",List.of("application/json")),(a,b)->true));when(transport.send(any(),anyString(),anyMap(),any())).thenReturn(response);}
 MockHttpServletRequest request(String method,String path){var r=new MockHttpServletRequest(method,path);r.setSecure(true);r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");return r;}
 @Test void onlyFourDeclaredOperationsAndTypesReachContent(){String id="01a10000-0000-7000-8000-000000000001";for(String kind:List.of("BOOKMARK","QUESTION","DECISION")){String path="/api/spaces/"+id+"/record-concepts/"+kind+"/"+id;for(String verb:List.of("GET","PUT"))assertEquals("content",GatewayRoute.select(verb,path).service());assertEquals("content",GatewayRoute.select("GET",path+"/revisions").service());assertNull(GatewayRoute.select("POST",path));assertNull(GatewayRoute.select("DELETE",path));assertNull(GatewayRoute.select("PUT",path+"/revisions"));}assertNull(GatewayRoute.select("GET","/api/spaces/"+id+"/record-concepts/NOTE/"+id));assertEquals("content",GatewayRoute.select("GET","/api/spaces/"+id+"/concept-references/"+id+"/records").service());}
 @Test void ambiguousMutationUnknownQueriesAndReadBodiesNeverReachOwner()throws Exception{String id="01a10000-0000-7000-8000-000000000001",path="/api/spaces/"+id+"/record-concepts/BOOKMARK/"+id;var body=request("GET",path);body.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->proxy.proxy(body));for(String query:List.of("type=BOOKMARK&type=QUESTION","unknown=x","after="+"a".repeat(257))){var r=request("GET","/api/spaces/"+id+"/concept-references/"+id+"/records");r.setQueryString(query);assertThrows(ResponseStatusException.class,()->proxy.proxy(r));}var put=request("PUT",path);put.setQueryString("limit=1");assertThrows(ResponseStatusException.class,()->proxy.proxy(put));verifyNoInteractions(transport);}
}
